import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        int n = dis.readInt();
        byte[] buffer = new byte[n];
        dis.readFully(buffer);
        String s = new String(buffer);
        char[] c = s.toCharArray();

        int[] totalCounts = new int[3];
        ArrayList<Integer>[] positions = new ArrayList[3];
        for (int i=0; i<3; i++) positions[i]=new ArrayList<>();
        int[] currentFreq = new int[3];
        int[] counts = new int[3];

        for (char ch : c) {
            for (int[] row : new int[c.length+1][3]) System.arraycopy(new int[3], 0, row, 0, 3);
            System.arraycopy(currentFreq, 0, totalCounts, 0, 3);
            int idx = Arrays.asList(totalCounts).indexOf(Collections.max(Arrays.asList(totalCounts)));
            switch (ch) {
                case 'V': currentFreq[0]++; counts[0]++; positions[0].add(c.indexOf(ch)); break;
                case 'K': currentFreq[1]++; counts[1]++; positions[1].add(c.indexOf(ch)); break;
                default: currentFreq[2]++; counts[2]++; positions[2].add(c.indexOf(ch)); break;
            }
        }

        int cv = counts[0], ck = counts[1], cs = counts[2];
        int[][][][] dp = new int[cv+1][ck+1][cs+1][3];
        for (int[][][] arr3D : dp) for (int[][] arr2D : arr3D) for (int[] arr1D : arr2D) Arrays.fill(arr1D, -1);

        System.out.println(search(0, 0, 0, 2, counts, positions, totalCounts, dp));
    }

    static int search(int v, int k, int s, int last, int[] counts, ArrayList<Integer>[] positions, int[] totalCounts, int[][][][] dp) {
        int cv = counts[0], ck = counts[1], cs = counts[2];
        if (v == cv && k == ck && s == cs) return 0;
        if (dp[v][k][s][last] != -1) return dp[v][k][s][last];
        int res = Integer.MAX_VALUE / 2;
        if (v < cv) {
            int p = positions[0].get(v);
            int moveCost = Math.max(totalCounts[p][0]-v,0)+Math.max(totalCounts[p][1]-k,0)+Math.max(totalCounts[p][2]-s,0)-1;
            res = Math.min(res, search(v+1,k,s,0,counts,positions,totalCounts,dp)+moveCost);
        }
        if (k<ck && last != 0) {
            int p = positions[1].get(k);
            int moveCost = Math.max(totalCounts[p][0]-v,0)+Math.max(totalCounts[p][1]-k,0)+Math.max(totalCounts[p][2]-s,0)-1;
            res = Math.min(res, search(v,k+1,s,1,counts,positions,totalCounts,dp)+moveCost);
        }
        if (s<cs) {
            int p = positions[2].get(s);
            int moveCost = Math.max(totalCounts[p][0]-v,0)+Math.max(totalCounts[p][1]-k,0)+Math.max(totalCounts[p][2]-s,0)-1;
            res = Math.min(res, search(v,k,s+1,2,counts,positions,totalCounts,dp)+moveCost);
        }
        return dp[v][k][s][last]=res;
    }
}
